function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*199999+59);var facts=['db A reachable','schema v3 supported','write permission granted','quota 80 percent used','backup completed','index fresh','api key valid','region us-east'];var steps=facts.map(function(f,i){return{step:i+1,action:'apply: '+f,needs_permission:f.indexOf('permission')>=0||f.indexOf('write')>=0,blocked:false};});steps.forEach(function(s){if(s.needs_permission&&R()<0.3)s.blocked=true;});var blocked=steps.filter(function(s){return s.blocked;}).length;return{facts:facts.length,plan_steps:steps.length,blocked_steps:blocked,plan_valid:blocked===0,dry_run:'ok'};}
var SEED = 93001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

